require __DIR__.'/../../src/bootstrap.php';$q=db()->prepare('SELECT * FROM products WHERE id=?');$q->execute([$_GET['id']??1]);$p=$q->fetch();if(!$p)fail_request('商品不存在。',404);
page($p['name'],function()use($p){echo '<div class="product-detail"><div class="product-art '.h($p['color']).'"><svg viewBox="0 0 240 220" role="img" aria-label="'.h($p['name']).'"><use href="/assets/products.svg#product-'.(int)$p['id'].'"></use></svg></div><section class="panel"><h2>'.h($p['name']).'</h2><p>'.h($p['description']).'</p><h2>¥'.h($p['price']).'</h2><p class="muted">库存 '.(int)$p['stock'].' 件</p><form action="/orders/create.php" method="post"><input type="hidden" name="product_id" value="'.(int)$p['id'].'"><input type="hidden" name="price" value="'.h($p['price']).'">'.csrf_field();echo '<label>购买数量<input type="number" name="quantity" value="1" min="1" max="20" required></label>';echo '<button>立即购买</button></form></section></div>';},'商品目录');
